125:  void set_l2c(bool present, uint64_t base)
127:    l2c_present_ = present;
128:    l2c_base_    = base;
169:    // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
275:    // v5: L2C MMIO config restore. Runs BEFORE the GPR loop (like the V sweep):
279:    // final value. See restore_l2c.
