379:      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
380:      pb_store_l2c_reg(off, state.l2c.reg[off / 8]);
384:  // One L2C register store: stage the MMIO address in x6 and the value's low
387:  // L2C control bits live in the low 32.
